/* Study 23: local legacy PM thread presentation. No API, clipboard or persistent storage. */
(function(){
'use strict';
const E=id=>document.getElementById(id),T=window.RelaxeStudyTheme,config={appearance:'light',palette:'blue',text:'1',width:'390'};
const dialog=E('thread-dialog'),content=E('thread-dialog-content'),body=E('thread-body');
const messages=[{sent:false,time:'Yesterday · 09:12',text:'The lower loop is open again. The first section is muddy, but the **viewpoint** is worth it.'},{sent:true,time:'Yesterday · 09:20',text:'Thanks! Is the turn marked from the main trail?'},{sent:false,time:'Yesterday · 09:25',text:'Yes — follow the wooden sign just after the bridge. An early start is usually quieter.'}];
let threadContext={id:'standalone',peer:'trailnotes',subject:'Route notes'};const adaptiveThreads=new Map();const peerLabel=()=>threadContext.peer.startsWith('r/')?threadContext.peer:'u/'+threadContext.peer;
let fixture='ready',pending=false,origin=null,allowNavigation=false;
const say=(id,text)=>{E(id).textContent=text;E(id).hidden=!text};
function theme(){const settings={foundation:'selected',...config},direction=T.directions[0],phone=E('thread-phone');for(const [key,value]of Object.entries(T.tokens(direction,settings)))phone.style.setProperty(key,value);T.setStyleAttributes(phone,direction,settings);phone.style.setProperty('--w',config.width+'px');phone.style.setProperty('--h',({360:800,390:844,600:960,720:480}[config.width])+'px');phone.dataset.largeText=String(+config.text>=2);window.RelaxeShell?.setContext({account:fixture==='guest'?'guest':'weekendreader',...config})}
function text(node,value){for(const line of value.split('\n')){const p=document.createElement('p'),pattern=/\*\*([^*]+)\*\*|\*([^*]+)\*|\[([^\]]+)\]\(([^)]+)\)/g;let last=0,m;while((m=pattern.exec(line))){p.append(document.createTextNode(line.slice(last,m.index)));const el=document.createElement(m[1]?'strong':m[2]?'em':'span');el.textContent=m[1]||m[2]||m[3];p.append(el);if(m[3])p.append(document.createTextNode(' ('+m[4]+')'));last=pattern.lastIndex}p.append(document.createTextNode(line.slice(last)));node.append(p)}}
function render(){E('thread-messages').replaceChildren();for(const [index,m]of messages.entries()){const li=document.createElement('li');li.dataset.sent=String(m.sent);const meta=document.createElement('p');meta.className='thread-message-meta';const author=document.createElement('span');author.textContent=m.sent?'You · u/weekendreader':peerLabel();const time=document.createElement('span');time.textContent=m.time;meta.append(author,time);const copy=document.createElement('div');copy.className='thread-message-body';text(copy,fixture==='long'&&index===0?m.text+'\n\n'+('The path follows the river before climbing through the trees. Bring water and allow time to stop. ').repeat(8):m.text);li.append(meta,copy);E('thread-messages').append(li)}}
function sync(){const disabled=pending||fixture==='guest';for(const f of E('thread-form').querySelectorAll('button,textarea'))f.disabled=disabled;E('thread-send').textContent=pending?'Sending…':'Send';E('thread-fixture').disabled=pending;say('thread-notice',fixture==='guest'?'Sign in to reply to a private message.':pending?'Sending reply…':'');E('thread-phone').dataset.presentation='bubbles';theme()}
function show(title,build){if(!dialog.open)origin=document.activeElement;E('thread-dialog-title').textContent=title;content.replaceChildren();build(content);dialog.showModal();E('thread-dialog-close').focus()}
function paragraph(node,value){const p=document.createElement('p');p.textContent=value;node.append(p)}
function action(node,label,callback){const b=document.createElement('button');b.type='button';b.textContent=label;b.addEventListener('click',callback);node.append(b)}
function leave(next){if(pending){show('Sending reply',node=>paragraph(node,'Wait for the current reply to finish before leaving this fixture.'));return}if(body.value===''){next();return}show('Discard message?',node=>{paragraph(node,'Your unsent message will be discarded.');const buttons=document.createElement('div');buttons.className='dialog-actions';action(buttons,'Keep writing',()=>dialog.close());action(buttons,'Discard message',()=>{body.value='';dialog.close();next()});node.append(buttons)})}
function format(kind){const pairs={bold:['**','**'],italic:['*','*'],link:['[','](https://example.com)'],strike:['~~','~~'],quote:['> ',''],list:['- ',''],numbered:['1. ',''],heading:['## ',''],spoiler:['>!','!<'],code:['`','`']},pair=pairs[kind];if(!pair)return;const value=body.value.slice(body.selectionStart,body.selectionEnd)||'text';if(dialog.open){origin=body;dialog.close()}body.setRangeText(pair[0]+value+pair[1],body.selectionStart,body.selectionEnd,'select');say('thread-error','');body.focus()}
for(const [id,key]of [['thread-appearance','appearance'],['thread-palette','palette'],['thread-scale','text'],['thread-width','width']])E(id).addEventListener('change',event=>{config[key]=event.target.value;theme()});
E('thread-fixture').addEventListener('change',()=>{fixture=E('thread-fixture').value;say('thread-error','');render();sync()});body.addEventListener('input',()=>{say('thread-error','');body.removeAttribute('aria-invalid')});
for(const b of E('thread-form').querySelectorAll('[data-thread-format]'))b.addEventListener('click',()=>format(b.dataset.threadFormat));
E('thread-more').addEventListener('click',()=>show('Formatting',node=>{const buttons=document.createElement('div');buttons.className='thread-format-options';for(const [key,label]of [['strike','Strikethrough'],['heading','Heading'],['list','Bulleted list'],['numbered','Numbered list'],['quote','Quote'],['spoiler','Spoiler'],['code','Inline code']])action(buttons,label,()=>format(key));node.append(buttons)}));
E('thread-preview').addEventListener('click',()=>show('Reply preview',node=>{paragraph(node,'To '+peerLabel()+' · '+threadContext.subject);text(node,body.value||'No reply yet.')}));
E('thread-form').addEventListener('submit',event=>{event.preventDefault();if(pending||fixture==='guest')return;if(body.value===''){body.setAttribute('aria-invalid','true');say('thread-error','Enter a reply.');body.focus();return}const task={text:body.value,failed:fixture==='failure'};pending=true;sync();setTimeout(()=>{pending=false;if(dialog.open&&E('thread-dialog-title').textContent==='Sending reply')dialog.close();if(task.failed)say('thread-error','Couldn’t send reply. Your writing is kept. Try again.');else{messages.push({sent:true,time:'Just now',text:task.text});body.value='';render();E('thread-scroll').scrollTop=E('thread-scroll').scrollHeight;say('thread-error','')}sync();body.focus({preventScroll:true})},900)});
E('thread-back').addEventListener('click',()=>leave(()=>{const url=new URL('navigation.html?destination=inbox&rev=18',location.href);for(const [key,value]of Object.entries({account:fixture==='guest'?'guest':'weekendreader',...config}))url.searchParams.set(key,value);location.href=url.href}));
E('thread-dialog-close').addEventListener('click',()=>dialog.close());dialog.addEventListener('close',()=>{if(origin?.isConnected&&!origin.disabled)origin.focus({preventScroll:true})});dialog.addEventListener('keydown',event=>{if(event.key!=='Tab')return;const items=[...dialog.querySelectorAll('button')],first=items[0],last=items.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus()}});
document.addEventListener('click',event=>{const b=event.target.closest('.shared-shell-nav [data-destination]');if(!b||b.dataset.destination==='search'||allowNavigation)return;if(!body.value&&!pending)return;event.preventDefault();event.stopImmediatePropagation();leave(()=>{allowNavigation=true;b.click()})},true);
E('thread-back').innerHTML=T.icon('back');E('thread-more').innerHTML=T.icon('more');E('thread-dialog-close').innerHTML=T.icon('close');render();sync();document.addEventListener('relaxe-shell-ready',theme,{once:true});E('thread-scroll').scrollTop=E('thread-scroll').scrollHeight;
if(new URLSearchParams(location.search).get('adaptive-screen')==='thread')window.RelaxeAdaptiveThread={guard:leave,back:()=>leave(()=>window.dispatchEvent(new Event('relaxe-workflow-close'))),configure(v){if(!v.row||!/^m[1-6]$/.test(v.row[0])||typeof v.row[1]!=='string'||typeof v.row[4]!=='string'||typeof v.row[5]!=='string')return false;if(threadContext.id!==v.row[0]){adaptiveThreads.set(threadContext.id,{messages:messages.map(m=>({...m})),scroll:E('thread-scroll').scrollTop});threadContext={id:v.row[0],peer:v.row[1],subject:v.row[4]};const saved=adaptiveThreads.get(threadContext.id);messages.splice(0,messages.length,...(saved?.messages||[{sent:false,time:v.row[6],text:v.row[5]}]));body.value='';render();E('thread-scroll').scrollTop=saved?.scroll||0}fixture=v.account==='guest'?'guest':'ready';E('thread-phone').querySelector('.thread-bar h2').textContent=peerLabel();E('thread-scroll').querySelector('h3').textContent=threadContext.subject;E('thread-scroll').querySelector('.field-help').textContent=v.account==='guest'?'Guest':'Account · u/weekendreader';for(const [id,key]of [['thread-appearance','appearance'],['thread-palette','palette'],['thread-scale','text']]){if(v[key]!==undefined){E(id).value=v[key];E(id).dispatchEvent(new Event('change',{bubbles:true}))}}sync();return true}};
})();
